 },
 {
 "name": "风林寺红川蝉",
 "description": "风林寺流的招式之一，具体动作未知，名称中的“川蝉”是一种鸟类，可能暗示了此招式的迅捷与精准。"
 },
 {
 "name": "飘移斩风羽 (Hyōi Kazekirihane)",
