 },
 "风林寺碎牙": {
 "nature": "父亲（未知）",
 "description": "对于父亲的存在，美羽只在长辈的只言片语中听说过，对他几乎一无所知。寻找失踪的父亲是她内心深处的一个愿望。"
 },
 "风林寺静羽": {
 "nature": "母亲（已故）",
 "description": "美羽对母亲的记忆模糊，只知道她在自己幼年时便已去世。对母亲的思念是她内心柔软的一部分。"
 },
 "梁山泊的师傅们": {
 "nature": "家人般的存在、长辈",
 "description": "美羽将岬越寺秋雨、马剑星、逆鬼至绪、阿帕查·波帕查、香坂时雨这五位师傅视为家人。她负责照顾他们的饮食起居，关系非常亲密。师傅们也都像对待亲生女儿或妹妹一样疼爱和保护着她。"
 }
 }
