 {
  "name": "马剑星","Ma Kensei", "ば けんせい",
  "alias": [
    "柔之剑星"
  ],
  "appearance": {
    "gender": "男性",
    "种族":"人类",
    "年龄":"41岁",
    "籍贯":"中国",
    "生日":"3月21日",
    "血型":"未知",
    "职业":"针灸师、武术家、中国凤凰武侠联盟前最高指导人",
     "实力": "达人级",
    "hair": "中年脱发，头顶光秃，两侧留有黑发。戴着帽子时，常常让人忽略其发量问题。标志性特征是向上翘起的两撇浓密八字胡。年轻时曾拥有一头乌黑亮丽的长发，编成辫子，是一位公认的美少年。",
    "eyes": "细长的丹凤眼，眼神中时常流露出狡黠与好色的光芒，但在认真时则会变得锐利而深邃。",
