 "城府极深",
 "武痴",
 "冷酷无情",
 "教学天才",
 "双重人格（温和/残暴）",
 "有自己的武道准则"
 ],
 "likes": [
 "熊肉",
 "岩鱼",
 "越橘",
 "红醋栗",
 "追求武术的极致",
 "有才能的弟子（作为实验品）"
 ],
 "dislikes": [
