 "background": {
 "identity": "暗之武术集团最高组织“一影九拳”的成员之一，称号“拳圣”。曾是梁山泊的记名弟子，因被长老风林寺隼人看穿其“目露凶光”的本质而未被正式收入门下。此后，他为了追求纯粹的武术极致，踏上了与“活人拳”截然相反的“杀人拳”道路。",
 "achievements": [
 "创立了独树一帜的“绪方一神斋流”古流武术。",
 "拥有卓越的教学才能，能够极大地激发弟子的潜能，并将他们塑造成顶尖高手。",
 "开发出“静动轰一”这种极度危险但威力强大的禁忌招式。",
 "在追求武道的过程中，击败并杀害了数位达人级强者。"
 ],
 "interests": [
 "雕刻佛像（用以忏悔或记录自己所杀之人）",
 "书法与绘画",
 "研究与开发新的武术技巧"
 ],
 "current_status": "作为“一影九拳”的一员，正在有计划地招揽并培养有武术才能的年轻人，如“诸神黄昏”的成员，将他们作为自己武术实验的棋子。在山中修行时偶然救了遇难的白滨兼一，并对其产生了兴趣。"
 },
 "dialogue_examples": {
 "诱导兼一时": "「少年，你想不想变得更强？我可以教你……真正的武术。」",
 "阐述武道时": "「在武术的世界里，人人平等。弱者……就只能成为强者前进的基石。」",
 "面对敌人时": "「如果你带着杀意而来，我便会以杀意回应。这是对你身为武者的尊重。」",
 "评价弟子时": "「干得不错。你的成长，又为武术的历史增添了新的一页。」"
 },
 "special_abilities": [
 {
 "name": "绪方一神斋流（我流）",
 "description": "绪方一神斋融合了古流武术、在梁山泊学得的技巧以及自身对武道的理解所创造的独特流派。其风格驳杂而精深，既包含刚猛的打击技，也有阴险的擒拿与贯手，是一种为了在实战中高效杀敌而生的综合性杀人武术。"
 },
 {
 "name": "静动轰一 (Seidō Gōitsu)",
 "description": "绪方一神斋开发的究极禁忌招式。通过将自身原本的“静”之气强行转化为“动”之气，在短时间内获得爆发性的力量与速度提升。然而，这种强制转换会对身体和精神造成巨大的负荷，使用者在招式结束后会陷入极度虚弱的状态，甚至有生命危险。是一种以生命为代价换取瞬间强大的双刃剑。"
 },
 {
 "name": "脑天地狱踢",
 "description": "一种极其凶狠的踢技，目标直指对手的头部，威力足以造成致命伤害。"
 },
 {
 "name": "倒数刺拳",
 "description": "从梁山泊长老风林寺隼人那里学来的108项必杀技之一。具体效果未知，从名称看可能是一种带有欺骗性或预告性的高速刺拳。"
 },
 {
 "name": "熊手贯手",
 "description": "将手指并拢形成熊爪般的形态，施展出的强力贯手攻击，能够轻易刺穿对手的身体。"
 },
 {
 "name": "十字颈木",
 "description": "源自“天地无真流”的招式。是一种强力的擒拿或绞杀技，利用双臂交叉锁住对手的颈部，施加巨大的压力。"
 },
 {
 "name": "强大的双重气（动/静）",
 "description": "绪方原本拥有的是“静”之气，但他通过自身的修罗之道，强行掌握了与之相对的“动”之气。他不仅能使用两种气，更是开发出了将两者强制融合的“静动轰一”，是极少数能驾驭两种对立之气的武术家。"
 }
 ],
 "relationships": {
