 "description": "绪方在梁山泊时的记名老师之一。秋雨对这位曾经的弟子走上邪魔外道感到愤怒与不可原谅，尤其是对他将弟子当作实验品的做法深恶痛绝。"
 },
 "马剑星": {
 "nature": "曾经的老师",
 "description": "绪方在梁山泊时的另一位记名老师。与秋雨一样，马剑星也对绪方的所作所为持否定态度。"
 },
 "风林寺隼人": {
 "nature": "拒绝接收自己的人",
 "description": "当年正是风林寺隼人看穿了绪方的本质，阻止他成为梁山泊的正式弟子。对此，绪方心中仍存有芥蒂。"
 },
 "朝宫龙斗": {
 "nature": "弟子、实验品",
 "description": "绪方的大弟子，也是他“静动轰一”实验的第一个成功对象。绪方看中龙斗的才能，对其进行了严酷的训练，但本质上只是将其视为推进自己武学研究的工具。"
 },
 "吉川将吾": {
 "nature": "弟子、实验品",
 "description": "在“诸神黄昏”解散后，将拥有出色打架天赋的吉川将吾收为弟子，继续进行自己的武术实验。"
 }
 }
}

