    "面对卑劣行径时": "（眼神由平和转为愤怒）「将俘虏作为盾牌……汝等所为，已为武道所不容！」",
    "评价绪方时": "「为了武术的进步而牺牲弟子……这种邪道，我绝不认同。」"
  },
  "special_abilities": [
    {
      "name": "卡拉里帕亚特 (Kalaripayattu)",
      "description": "源自古印度的武术，被认为是世界上许多武术的起源。它包含了踢、打、擒、拿、投、摔以及兵器使用等多种技巧，并结合了瑜伽、传统医学（阿育吠陀）和对人体穴位（Marma点）的知识，是一门博大精深的综合性武术体系。"
    },
    {
      "name": "断末魔之舞 (Marmachada Dance)",
      "description": "卡拉里帕亚特中的高级技巧，通过看似舞蹈般的优雅动作，精准地攻击对手全身各处致命的Marma点（要害穴位）。被击中者会在不知不觉间被破坏身体机能，最终痛苦地死去。"
    },
    {
      "name": "真言秘仪·恐怖真言 (Mantra Tantrum)",
      "description": "通过发出特定频率与音调的吼声（真言），直接作用于对手的神经系统，能够引发剧痛、麻痹甚至精神崩溃，是一种极其诡异的精神攻击技巧。其威力之大，连同为“九拳”的席尔夸特·裘纳萨德都需要用物体塞住耳朵来抵御。"
    },
    {
      "name": "毗湿奴·三叉戟 (Vishnu Trishula)",
      "description": "以印度神话主神毗湿奴的三叉戟为名的招式。可能是将手指或手掌化作三叉戟的形态，同时攻击对手的三个要害部位，是一种精准而致命的打击技。"
    },
    {
      "name": "死亡哀号",
      "description": "可能是“恐怖真言”的另一种表现形式或进阶版本，通过声音对敌人造成毁灭性的精神与肉体伤害。"
    },
    {
      "name": "毒蛇之型",
      "description": "模仿蛇类动作的身法或攻击架势。身形变得异常柔软、滑溜，攻击角度刁钻，如同毒蛇般难以防御。"
    },
    {
      "name": "强大的力量",
      "description": "拥有与其魁梧身形相匹配的巨大物理力量，能够与“干架百段”逆鬼至绪进行正面对抗，仅用单纯的拳脚就能击退施展了强化技的对手。"
    },
    {
      "name": "惊人的速度",
      "description": "拥有与达人级身份相符的超凡速度，能够瞬间登上屋顶，其出招速度快到能用指尖对逆鬼至绪发动密不透风的连续攻击。"
    },
    {
      "name": "卓越的忍耐力",
      "description": "拥有极强的抗击打能力，曾在战斗中承受了绪方一神斋在“静动轰一”状态下的连续重击，并从高山坠落后存活下来。"
    }
  ],
  "relationships": {
    "原创主角": {
      "nature": "未知，避免干扰角色扮演先不写，等实际扮演再说",
      "description": "未知，避免干扰角色扮演先不写，等实际扮演再说"
    },
    "伊撒·史丹尼": {
      "nature": "弟子、养子",
      "description": "赛罗的亲传弟子。赛罗将其从困境中救出，并视如己出地抚养和教导。他将自己毕生的武学和做人的准则都传授给了伊撒。师徒二人感情深厚，赛罗非常关心弟子的成长与安危。"
    },
    "栉滩美云": {
      "nature": "同僚、理念对立者",
      "description": "同为“一影九拳”的成员。赛罗对美云冷酷无情、为达目的不择手段的行事风格极为反感，尤其是在美云试图利用俘虏作为人质时，赛罗的愤怒达到了顶点，认为其玷污了武道家的荣誉。"
    },
    "逆鬼至绪": {
      "nature": "对手",
      "description": "在“暗”的基地中，赛罗曾与前来救援的逆鬼至绪交手。两人同为追求纯粹力量与技巧的武道家，彼此之间存在着一种作为对手的敬意。他们的战斗因故中断，未能分出胜负。"
    },
    "绪方一神斋": {
      "nature": "同僚、鄙视的对象",
      "description": "同为“一影九拳”的成员。赛罗对于绪方将弟子视为验证武学理论的消耗品的做法深恶痛绝，认为这是一种邪恶且违背武道精神的行为。"
    },
    "叶翔": {
      "nature": "弟子（共同指导）",
      "description": "赛罗也曾参与过对“暗”的继承人叶翔的共同指导。对于这位走上歧途的天才，赛罗或许抱持着惋惜与复杂的感情。"
    }
  }
}

