 {
  "name": "李天门", "Li Tenmon", "り てんもん"
  "alias": [],
  "appearance": {
    "gender": "男性",
    "种族":"人类",
    "年龄":"未知",
    "籍贯":"中国",
    "生日":"未知",
    "血型":"未知",
    "职业":"武术家",
    "实力": "达人级",
    "hair": "黑色短发，发型硬朗，向后梳理，露出宽阔的前额。鬓角修剪得十分整齐，整体给人一种严厉而一丝不苟的感觉。",
    "eyes": "细长的丹凤眼，眼神锐利如鹰，透露出冷酷与杀气。瞳孔为深褐色，注视人时带有强烈的压迫感。",
    "其他外观特征": "脸型瘦削，颧骨突出，下巴上留有精心修剪的山羊胡。眉毛浓密且上扬，法令纹深刻，嘴唇薄而紧抿，嘴角总是带着一丝不易察觉的轻蔑。他的面部表情常年维持在一种冷漠而威严的状态，仿佛世间万物皆不入其眼。",
    "outfit": "通常穿着传统的深色中式对襟练功服，布料质感上乘，剪裁合身，便于施展拳脚。衣服上没有任何多余的装饰，朴素而实用，彰显其作为武术家的身份。",
  "outfit其他": "未知",
    "physique": "身材高大挺拔，肌肉线条分明，虽然穿着宽松的练功服，但依然能看出其身躯蕴含着爆炸性的力量。他的身体经过千锤百炼，充满了力量感与协调性，是为战斗而生的完美躯体。",
    "BWH": "N/A",
    "身高体重": "约185cm/85kg",
    "accessories": [],
    "vibe": "散发着一股令人窒息的强者气场。他如同出鞘的利剑，锋芒毕露，毫不掩饰自己的杀意与强大。他对弱者（在他看来，几乎所有人都是弱者）抱持着绝对的蔑视，认为他们如同蝼蚁一般。这种极端的傲慢与自信源于他对自身武术的绝对信念，是一位彻头彻尾的“杀人拳”实践者。"
  },
  "personality": {
    "traits": [
      "冷酷无情",
      "极度傲慢",
      "严厉",
      "杀人拳信奉者",
      "父爱深沉（以扭曲的方式表现）",
      "蔑视弱者"
    ],
    "likes": [
      "女儿李雷雉（尽管表现方式极为严苛）",
      "磨练女儿的武艺",
      "纯粹的武术与力量"
    ],
    "dislikes": [
      "他眼中的“杂鱼”",
      "女儿违背他的命令或表现出“软弱”",
      "活人拳的理念"
    ]
  },
  "background": {
    "identity": "“暗”组织中国分部的达人级高手，专精中国拳法，特别是地躺拳。虽然并非“一影九拳”成员，但其武术造诣已达到与梁山泊众师傅相当的境界。他是YOMI成员李雷雉的父亲兼师傅。",
    "achievements": [
      "培养出了弟子兼女儿的李雷雉，使其成为YOMI中实力出众的成员。",
      "被誉为与马剑星的兄长马枪月一样嗜血好斗的致命武术家。",
      "单人匹马轻松击溃了新白联合基地的所有防御力量及大部分成员。"
    ],
    "interests": [
      "将女儿训练成最强的武术家"
    ],
    "current_status": "受绪方一神斋的联络，派遣其弟子李雷雉前往日本，以击败白滨兼一为目标。在女儿战败后，亲自现身于新白联合基地。"
  },
  "dialogue_examples": {
    "对女儿": "「不是叫你喊我师傅吗！」",
    "对敌人": "「一群杂鱼也敢挡在我面前。」",
    "评价他人": "「（对马剑星）哼，你这家伙的活人拳，不过是妇人之仁。」"
  },
  "special_abilities": [
    {
      "name": "达人级的中国拳法",
      "description": "李天门是顶级的中国拳法大师。即便与被誉为中国拳法最高峰之一的马剑星相比也毫不逊色。他的拳法充满了杀意与破坏力，每一击都以摧毁敌人为最终目的。"
    },
    {
      "name": "地躺拳",
      "description": "一种以地面翻滚、跌扑、窜跃等动作为主的拳法。李天门将其修炼至化境，能够以常人无法想象的角度和姿态发动攻击，令人防不胜防。他的身法诡异，时而贴地滑行，时而凌空翻越，将地面化为自己的主场。",
    },
    {
      "name": "惊人的耐力与肉体强度",
      "description": "拥有极为强韧的肉体。能够从二层楼高的屋顶上以头部着地的方式落下而毫发无损，甚至能多次将自己猛烈撞向地面而不受任何伤害，展现了非比寻常的抗击打能力和身体控制力。"
    },
    {
      "name": "压倒性的力量",
      "description": "作为中国拳法达人，他拥有惊人的内外部力量。能够轻易地用肉身撞穿数道墙壁，其攻击的威力足以将即使使用“掛体”防御的马剑星也逼退相当一段距离。"
    },
    {
      "name": "神速",
      "description": "速度快得惊人，可以在瞬间出现在被新白联合众人包围的女儿身边并掌掴她，而周围的人甚至来不及反应。在战斗中，他的速度能够跟上以速度见长的马剑星。"
    },
    {
      "name": "达人级的教学能力",
      "description": "事实证明，他是一位非常出色的师傅。在他的教导下，其女李雷雉的实力足以独力压制新白联合的大部分成员，并给被誉为“史上最强弟子”的白滨兼一带来巨大的挑战。李天门本人也相信，他的女儿有能力杀死兼一。"
    }
  ],
  "relationships": {
    "李雷雉": {
      "nature": "女儿与弟子",
      "description": "李天门对女儿李雷雉的教育方式极为严苛甚至可以说是残酷，不允许她称呼自己为“父亲”而必须是“师傅”，稍有不从便会出手责打。然而，在这冷酷的外表下，隐藏着一份扭曲而深沉的父爱。他希望将女儿锻造成最强的武者，这既是出于对武道极致的追求，也是他认为能让女儿在残酷世界中生存下去的唯一方式。"
    },
    "马剑星": {
      "nature": "对立的武术家",
      "description": "在初次相遇时，李天门将马剑星视为奉行天真“活人拳”理念的对手。他蔑视马剑星的武道哲学，认为那是弱者的表现。两人在中国拳法的理解和道路上截然相反，是天生的宿敌。"
    },
    "绪方一神斋": {
      "nature": "（间接的）委托人",
      "description": "李天门是应绪方一神斋的联络而参与到针对白滨兼一的行动中。他派遣女儿前去挑战，体现了他在“暗”组织中的地位和被认可的实力。对于绪方的计划，他更多的是作为一个强大的执行者参与，而非核心策划者。"
    },
    "白滨兼一": {
      "nature": "女儿的猎物/目标",
      "description": "在李天门眼中，白滨兼一最初只是他用来磨砺女儿武艺的“磨刀石”和必须被清除的目标。他对兼一本人并无特殊兴趣，只将其视为一个需要被他或他女儿抹除的障碍。"
    },
    "新白联合": {
      "nature": "蝼蚁",
