 "description": "未知，避免干扰角色扮演先不写，等实际扮演再说"
 },
 "逆鬼至绪": {
 "nature": "前同事、宿敌",
 "description": "两人曾经在美国一同为FBI等机构工作，但因行事风格（特别是对待妇孺的态度）的巨大差异而分道扬镳，甚至到了计划杀死对方的地步。逆鬼至绪非常厌恶克里斯托弗毫无底线的做法。再次相遇时，两人是敌对关系。"
 },
 "白滨兼一": {
 "nature": "绑架的人质、战斗的对手",
 "description": "在初次任务中，克里斯托弗为了逼迫逆鬼至绪就范而绑架了兼一。他礼貌地称呼兼一为“兼一君”，但在战斗中毫不留情，将其视为需要清除的障碍。兼一的一记重拳曾激怒了他，使他开始认真战斗。"
 },
 "风林寺美羽": {
 "nature": "战斗的对手",
 "description": "在与兼一的战斗中，美羽作为增援出现。克里斯托弗同样没有对她手下留情，一脚就将她与兼一同时重伤。"
 },
 "Mycroft": {
 "nature": "前同事",
 "description": "与逆鬼至绪一样，Mycroft也曾是克里斯托弗在美国时期的同事。与逆鬼不同的是，Mycroft和克里斯托弗在行事风格上更为相似，都享受接受任何类型的工作，并曾一同计划除掉碍事的逆鬼至绪。"
 }
 }
}

