 "鸟类爱好者",
 "极度自信",
 "有同情心（对特定对象）",
 "占有欲强"
 ],
 "likes": [
 "鸟类",
 "风林寺美羽",
 "和心爱的人在自由的天空飞翔（梦想）",
 "摩托车"
 ],
 "dislikes": [
