{
  "name": "锻冶摩里巳", "Kajima Satomi", "かじま さとみ",
  "alias": [
    "影",
    "一目连 (Ichimokuren)"
  ],
  "appearance": {
    "gender": "男性",
    "种族": "人类",
    "年龄": "19岁",
    "籍贯": "日本",
    "生日": "未知",
    "血型": "未知",
    "职业": "YOMI首领",
    "实力": "弟子级（顶尖）",
    "hair": "一头深棕色的凌乱短发，发丝粗硬，充满野性的不羁感，显得有些参差不齐。",
    "eyes": "榛色的眼瞳，右眼完好，眼神通常平静无波，甚至带有一丝幽默感，但深处隐藏着对武术的偏执与疯狂。左眼戴着一个黑色的眼罩，遮盖着在严酷训练中失去的眼睛。",
    "其他外观特征": "拥有古铜色的健康肌肤，全身布满了无数在严酷训练和实战中留下的伤疤，这些伤疤是他为追求武道极致而付出的证明，也是其强大实力的勋章。",
