      "nature": "猎物、被评估的对象",
      "description": "柯奇来到荒凉高中的首要目标。他通过精密的计划，一步步将兼一引入陷阱，不仅在肉体上重创了他，更是在其内心植入了深深的恐惧。在他看来，初遇时的兼一虽然潜力未显，但其“活人拳”的理念与自己所信奉的“杀人拳”截然相反，是必须予以否定的存在。"
    },
    "阿加德·贾姆塞": {
      "nature": "师傅",
      "description": "柯奇的古流泰拳师傅。阿加德以独特的问答方式在实战中教导柯奇，锻炼其观察力和判断力。柯奇对这位实力深不可测的师傅抱有极大的敬畏乃至恐惧，严格遵守其每一道指令。"
    },
    "锻冶摩里巳": {
      "nature": "同僚、棋盘上的对手",
      "description": "同为YOMI的核心成员。两人智力超群，经常在棋盘上对弈，柯奇的胜率更高。锻冶摩对柯奇的分析能力给予了高度评价，两人之间是既合作又竞争的关系。"
    },
    "谷本夏": {
      "nature": "外观相似的同僚",
      "description": "同为YOMI成员，两人的发型、发色、体格乃至冷静理智的性格都有诸多相似之处。"
    }
  }
}

